import { chromium } from 'playwright'

const browser = await chromium.launch({ args: ['--no-sandbox'] })
const page = await browser.newPage()

const sawLoading = []
page.on('console', (msg) => {
  if (msg.text().includes('__LOADING_SEEN__')) sawLoading.push(Date.now())
})

// Observe DOM mutations for the "Loading category..." text so we catch even a 1-frame flash.
await page.addInitScript(() => {
  window.__loadingFlashes = 0
  const observer = new MutationObserver(() => {
    if (document.body && document.body.innerText.includes('Loading category...')) {
      window.__loadingFlashes++
      console.log('__LOADING_SEEN__')
    }
  })
  document.addEventListener('DOMContentLoaded', () => {
    observer.observe(document.body, { childList: true, subtree: true, characterData: true })
  })
})

await page.goto('http://localhost:3000')
await page.waitForSelector('text=Products on sale')

// Give the mount-time prefetch (and the artificial 800ms API delay) time to resolve.
await page.waitForTimeout(1200)

const before = Date.now()
await page.click('text=Products on sale')
await page.waitForURL('**/catalog?category=sale')
await page.waitForSelector('h2')
const after = Date.now()

const heading = await page.textContent('h2')
const products = await page.$$eval('li', (els) => els.map((e) => e.textContent))
const url = page.url()
const flashes = await page.evaluate(() => window.__loadingFlashes)

console.log(JSON.stringify({
  url,
  heading,
  products,
  navigationMs: after - before,
  loadingFlashes: flashes,
}, null, 2))

await browser.close()

